//! The SSE2 intrinsics the decoder kernels use, implemented with WebAssembly simd128, so that
//! `lossy::sse2` and `lossless::decoder::sse2` build for wasm32 as they are. Every function
//! gives the result of its SSE2 namesake bit for bit for the arguments the kernels pass:
//! immediates are const generics as in `core::arch::x86_64`, and shift counts past the lane
//! width behave as on x86.
//!
//! Generated by a script from the list of intrinsics the kernels call; a kernel that starts
//! using another SSE2 intrinsic needs it added here.
#![forbid(unsafe_code)]
#![allow(non_camel_case_types, dead_code)]

use core::arch::wasm32::*;

pub(crate) type __m128i = v128;

/// Unaligned loads and stores through array references, as `safe_unaligned_simd::x86_64`.
pub(crate) mod mem {
    use core::arch::wasm32::*;
    pub(crate) use safe_unaligned_simd::wasm32::{
        v128_load as _mm_loadu_si128, v128_load64_zero as _mm_loadu_si64, v128_store as _mm_storeu_si128,
    };

    #[inline(always)]
    pub(crate) fn _mm_storeu_si64(dst: &mut [u8; 8], a: v128) {
        *dst = i64x2_extract_lane::<0>(a).to_le_bytes();
    }
}

